def classify_existing_units(apps, schema_editor):
    Unit = apps.get_model("masters", "Unit")
    taken = set()
    for unit in Unit.objects.filter(deleted_at__isnull=True).order_by("created_at"):
        known = KNOWN_UNITS.get(unit.code.strip().lower())
        if not known:
            unit.uom_type = "Other"
            unit.save(update_fields=["uom_type"])
            continue
        uom_type, places, factor, is_base = known
        key = (unit.client_id, uom_type)
        if is_base and key in taken:
            is_base = False  # one base unit per type per tenant
        if is_base:
            taken.add(key)
        unit.uom_type = uom_type
        unit.decimal_places = places
        unit.conversion_factor = factor
        unit.is_base_unit = is_base
        unit.save(update_fields=["uom_type", "decimal_places", "conversion_factor", "is_base_unit"])


